mapper.select:
SELECT report_id, lawd_cd, deal_ymd, collected_at, item_count, jeonse_count, monthly_rent_count
FROM batch_estate_rent_reports
WHERE report_id = #{reportId}

mapper.insert:
INSERT INTO houserents (apt_seq, floor, deal_year, deal_month, deal_day, exclu_use_ar, deposit, monthly_rent, contract_term, contract_type, use_rr_right, pre_deposit, pre_monthly_rent, source_hash) SELECT v.apt_seq, v.floor, v.deal_year, v.deal_month, v.deal_day, v.exclu_use_ar, v.deposit, v.monthly_rent, v.contract_term, v.contract_type, v.use_rr_right, v.pre_deposit, v.pre_monthly_rent, SHA2(CONCAT_WS('|', v.apt_seq, v.floor, v.deal_year, v.deal_month, v.deal_day, v.exclu_use_ar, v.deposit, v.monthly_rent, v.contract_term, v.contract_type, v.use_rr_right, v.pre_deposit, v.pre_monthly_rent), 256) AS source_hash FROM (
SELECT CONCAT('BT', #{item.lawdCd}, '-', SUBSTRING(MD5(CONCAT_WS('|', #{item.lawdCd}, #{item.dong}, #{item.jibun}, #{item.aptName})), 1, 10)) AS apt_seq, CAST(#{item.floor} AS CHAR) AS floor, CAST(SUBSTRING(#{item.dealDate}, 1, 4) AS UNSIGNED) AS deal_year, CAST(SUBSTRING(#{item.dealDate}, 6, 2) AS UNSIGNED) AS deal_month, CAST(SUBSTRING(#{item.dealDate}, 9, 2) AS UNSIGNED) AS deal_day, #{item.area} AS exclu_use_ar, #{item.deposit} AS deposit, #{item.monthlyRent} AS monthly_rent, #{item.contractTerm} AS contract_term, #{item.contractType} AS contract_type, #{item.useRrRight} AS use_rr_right, #{item.preDeposit} AS pre_deposit, #{item.preMonthlyRent} AS pre_monthly_rent
) v WHERE v.deal_year IS NOT NULL AND v.deal_year > 0 ON DUPLICATE KEY UPDATE contract_term = VALUES(contract_term), contract_type = VALUES(contract_type), use_rr_right = VALUES(use_rr_right), pre_deposit = VALUES(pre_deposit), pre_monthly_rent = VALUES(pre_monthly_rent)

mapper.update:
UPDATE houseinfos
SET latitude = #{latitude}, longitude = #{longitude}
WHERE apt_seq = #{aptSeq}
